-- Identity, passwordless sign-in and audit trail (MVP decisions R03, R05, R07).
-- Identifiers are UUIDv7 generated by the application. Timestamps are UTC (timestamptz).
-- No purge: users are disabled, never deleted; audit events are append-only.

CREATE TABLE users (
  id            uuid PRIMARY KEY,
  email         text NOT NULL,
  display_name  text NOT NULL,
  role          text NOT NULL CHECK (role IN ('enterprise_administrator')),
  status        text NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'disabled')),
  locked_until  timestamptz,
  created_at    timestamptz NOT NULL DEFAULT now(),
  updated_at    timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT users_email_normalised CHECK (email <> '' AND email = lower(btrim(email)))
);
CREATE UNIQUE INDEX users_email_key ON users (email);

-- One-time sign-in codes. Only a hash of the code is stored.
CREATE TABLE login_codes (
  id           uuid PRIMARY KEY,
  user_id      uuid NOT NULL REFERENCES users (id),
  code_hash    text NOT NULL,
  attempts     integer NOT NULL DEFAULT 0 CHECK (attempts >= 0),
  expires_at   timestamptz NOT NULL,
  consumed_at  timestamptz,
  created_at   timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX login_codes_open_idx ON login_codes (user_id, created_at DESC) WHERE consumed_at IS NULL;

-- Sessions. Only a hash of the session token is stored.
CREATE TABLE sessions (
  id          uuid PRIMARY KEY,
  user_id     uuid NOT NULL REFERENCES users (id),
  token_hash  text NOT NULL UNIQUE,
  created_at  timestamptz NOT NULL DEFAULT now(),
  expires_at  timestamptz NOT NULL,
  revoked_at  timestamptz
);
CREATE INDEX sessions_user_idx ON sessions (user_id);

-- Append-only audit trail. Never holds secrets or restricted source bodies.
CREATE TABLE audit_events (
  id             uuid PRIMARY KEY,
  occurred_at    timestamptz NOT NULL DEFAULT now(),
  actor_user_id  uuid REFERENCES users (id),
  action         text NOT NULL,
  subject_type   text,
  subject_id     text,
  detail         jsonb NOT NULL DEFAULT '{}'::jsonb
);
CREATE INDEX audit_events_occurred_idx ON audit_events (occurred_at);

CREATE FUNCTION audit_events_append_only() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  RAISE EXCEPTION 'audit_events is append-only';
END;
$$;

CREATE TRIGGER audit_events_no_update_delete
  BEFORE UPDATE OR DELETE ON audit_events
  FOR EACH ROW EXECUTE FUNCTION audit_events_append_only();

CREATE TRIGGER audit_events_no_truncate
  BEFORE TRUNCATE ON audit_events
  FOR EACH STATEMENT EXECUTE FUNCTION audit_events_append_only();
